@Polynomial.hasseDeriv_mul : ∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f g : Polynomial R),
  (Polynomial.hasseDeriv k) (f * g) =
    ∑ ij ∈ Finset.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g

@AlgHom.map_det : ∀ {n : Type u_4} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type u_1} [inst_2 : CommRing R]
  {S : Type u_2} [inst_3 : CommRing S] [inst_4 : Algebra R S] {T : Type u_3} [inst_5 : CommRing T]
  [inst_6 : Algebra R T] (f : S →ₐ[R] T) (M : Matrix n n S), f M.det = (f.mapMatrix M).det

@IsLocalization.exists_integer_multiple : ∀ {R : Type u_1} [inst : CommSemiring R] (M : Submonoid R) {S : Type u_2}
  [inst_1 : CommSemiring S] [inst_2 : Algebra R S] [IsLocalization M S] (a : S),
  ∃ b, IsLocalization.IsInteger R (↑b • a)

@IsLocalization.surj_of_gcd_domain : ∀ {R : Type u_1} {A : Type u_2} [inst : CommRing R] [inst_1 : CommRing A]
  [inst_2 : Algebra R A] [inst_3 : GCDMonoid R] (M : Submonoid R) [IsLocalization M A] (z : A),
  ∃ a b, IsUnit (gcd a b) ∧ z * (algebraMap R A) b = (algebraMap R A) a

@MvPolynomial.degrees_map_of_injective : ∀ {R : Type u_1} {S : Type u_2} {σ : Type u_3} [inst : CommSemiring R]
  [inst_1 : CommSemiring S] (p : MvPolynomial σ R) {f : R →+* S},
  Function.Injective ⇑f → ((MvPolynomial.map f) p).degrees = p.degrees
